ServiceLoader<CodecFactory> loader = ServiceLoader.load(CodecFactory.class);
for (CodecFactory factory : loader) {            // located lazily, cached per loader
    Encoder encoder = factory.getEncoder("PNG");
    if (encoder != null) { use(encoder); break; }
}
loader.reload();                                 // drop the provider cache, re-resolve

